#[test]
fn share_and_free_original_first() {
    unsafe {
        let config = default_config();
        let mut handle: *mut SweEphemeris = ptr::null_mut();
        let mut err = [0u8; 256];
        swisseph_ffi::swisseph_new(&config, &mut handle, err.as_mut_ptr() as *mut c_char, err.len());

        let mut shared: *mut SweEphemeris = ptr::null_mut();
        let ret = swisseph_ffi::swisseph_share(handle, &mut shared, err.as_mut_ptr() as *mut c_char, err.len());
        assert_eq!(ret, SweErrorCode::Ok as i32);
        assert!(!shared.is_null());

        // Free original first — shared must still work
        swisseph_ffi::swisseph_free(handle);

        let mut xx = [0.0f64; 6];
        let mut flags_used: i32 = 0;
        let ret = swisseph_ffi::swisseph_calc_ut(
            shared, 2451545.0, 0, 256,
            ptr::null(), ptr::null(), xx.as_mut_ptr(), &mut flags_used,
            err.as_mut_ptr() as *mut c_char, err.len(),
        );
        assert_eq!(ret, 0);

        swisseph_ffi::swisseph_free(shared);
    }
}

