### Step 8: Add concurrent share/free test in `tests/concurrency.rs`

N threads compute over shared handles while others free theirs — no UB, no panics. This is the acceptance-criteria concurrency test.

```rust
#[test]
fn concurrent_shared_handles_with_interleaved_free() {
    let original = unsafe { make_handle() };
    let baseline = unsafe { compute_all_ffi(original) };

    // Create N shared handles
    let n = 8;
    let handles: Vec<*mut SweEphemeris> = (0..n).map(|_| unsafe {
        let mut shared: *mut SweEphemeris = ptr::null_mut();
        let mut err = [0u8; 256];
        let ret = swisseph_ffi::swisseph_share(original, &mut shared, err.as_mut_ptr() as *mut c_char, err.len());
        assert_eq!(ret, SweErrorCode::Ok as i32);
        shared
    }).collect();

    // Free the original — all shared handles still valid
    unsafe { swisseph_ffi::swisseph_free(original) };

    // N threads each calc on their own shared handle then free it
    std::thread::scope(|s| {
        let threads: Vec<_> = handles.into_iter().enumerate().map(|(i, h)| {
            s.spawn(move || {
                let results = unsafe { compute_all_ffi(h) };
                unsafe { swisseph_ffi::swisseph_free(h as *mut _) };
                (i, results)
            })
        }).collect();
        for t in threads {
            let (i, results) = t.join().expect("thread panicked");
            assert_eq!(results, baseline, "shared handle thread {i} diverged");
        }
    });
}
```

